        const t = (s || "").replace(/<\/?[a-z]{1,8}>/gi, " ").replace(/~~|\*\*|__/g, " ").replace(/\s+/g, " ").trim();
        if (!t || t.length > 600) return false;
        const ws = t.split(/\s+/);
