        const hits = []; for (let i = 0; i < words.length; i++) if (tw.includes(instNorm(words[i]).split(" ")[0])) hits.push(i);
        for (const h of hits) for (let a = Math.max(0, h - 13); a <= h; a++) for (let b = Math.min(words.length, a + 14); b > Math.max(a + 1, h); b--) {
            const n = instNorm(words.slice(a, b).join(" "));
            if (n.split(" ").length < 2 || !set.has(n)) continue;
            const ns = " " + n + " ";
            if (tw.every(x => ns.includes(" " + x + " "))) return words.slice(a, b).join(" ");
        }
        const CAP = /(?:(?:[A-Z][A-Za-z.'&-]*|of|and|for|the|de|&)[ \t,]+){0,8}(?:[A-Z][A-Za-z.'-]*)/g;
        let m;
