        const memo = new Map();
        const seg = (i, n) => { if (i === t.length) return n >= 2; const key = i * 10 + Math.min(n, 9); if (memo.has(key)) return memo.get(key); let r = false; for (let j = Math.min(t.length, i + 12); j >= i + 3 && !r; j--) if (part(t.slice(i, j)) && seg(j, n + 1)) r = true; memo.set(key, r); return r; };
        let suf = false; for (const x of NAME_SUFFIXES) if (x.length >= 3 && t.endsWith(x) && t.length - x.length >= 3) { suf = true; break; }
